392	func TestRejectFlow(t *testing.T) {
393		w, _ := setupApproval(t)
394		if _, err := w.Apply(approvalApply()); err != nil {
395			t.Fatal(err)
396		}
397	
398		// 空理由、全空白理由：参数错误，请求保持不变。
399		for _, reason := range []string{"", "   ", "\t\n"} {
400			if _, err := w.Reject("u1", "r1", "sa", "dev-approve", reason); !errors.Is(err, ErrInvalidArgument) {
401				t.Fatalf("reason %q err = %v, want ErrInvalidArgument", reason, err)
402			}
403		}
404		req, _ := w.Request("u1", "r1")
405		if req.State != RequestPendingApproval {
406			t.Fatalf("state = %v, want still pending", req.State)
407		}
408	
409		// 无权会话不能拒绝。
410		if _, err := w.Reject("u1", "r1", "s1", "dev1", "no"); !errors.Is(err, ErrNotApprover) {
411			t.Fatalf("err = %v, want ErrNotApprover", err)
412		}
413	
414		// 正常拒绝：拒绝终态，不产生退款（本就没冻结）。
415		req, err := w.Reject("u1", "r1", "sa", "dev-approve", "duplicate order")
416		if err != nil {
417			t.Fatal(err)
418		}
419		if req.State != RequestRejected || req.RejectReason != "duplicate order" {
420			t.Fatalf("rejected request = %+v", req)
421		}
422		if req.DecidedAt.IsZero() || req.ApproverAccountID != "payer" {
423			t.Fatalf("decision fields missing: %+v", req)
424		}
425		bal, _ := w.Balance("payer")
426		if bal != (Balances{Available: 100, Reserved: 0}) {
427			t.Fatalf("balance = %+v, want untouched", bal)
428		}
429	
430		// 账本含拒绝留痕。
431		var found bool
432		for _, e := range w.Ledger() {
433			if e.Kind == LedgerRejection && e.RequestID == "r1" {
434				found = true
435				if e.AccountID != "u1" || e.Amount != 0 || e.Reason != "duplicate order" {
436					t.Fatalf("rejection entry = %+v", e)
437				}
438			}
439		}
440		if !found {
441			t.Fatal("missing LedgerRejection entry")
442		}
443	
444		// 重复拒绝且理由一致：幂等，不重复留痕。
445		before := len(w.Ledger())
446		if _, err := w.Reject("u1", "r1", "sa", "dev-approve", "duplicate order"); err != nil {
447			t.Fatalf("idempotent reject: %v", err)
448		}
449		if len(w.Ledger()) != before {
450			t.Fatal("ledger grew on idempotent reject")
451		}
452		// 理由不同：冲突。
453		if _, err := w.Reject("u1", "r1", "sa", "dev-approve", "different reason"); !errors.Is(err, ErrConflict) {
454			t.Fatalf("different reason err = %v, want ErrConflict", err)
455		}
456	}
