496			t.Fatalf("balance = %+v, want untouched", bal)
497		}
498		var found bool
499		for _, e := range w.Ledger() {
500			if e.Kind == LedgerCancellation && e.RequestID == "r1" {
501				found = true
502				if e.AccountID != "u1" || e.Amount != 0 {
503					t.Fatalf("cancellation entry = %+v", e)
504				}
505			}
506		}
507		if !found {
508			t.Fatal("missing LedgerCancellation entry")
509		}
510		// 重复取消幂等。
511		before := len(w.Ledger())
512		if _, err := w.Cancel("u1", "r1"); err != nil {
513			t.Fatalf("repeat cancel: %v", err)
514		}
515		if len(w.Ledger()) != before {
516			t.Fatal("ledger grew on repeat cancel")
517		}
518		// 已取消不能批准、不能结算。
519		if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); !errors.Is(err, ErrRequestNotPending) {
520			t.Fatalf("approve cancelled err = %v, want ErrRequestNotPending", err)
521		}
522		if _, err := w.Settle("u1", "r1", 0); !errors.Is(err, ErrAlreadyCancelled) {
523			t.Fatalf("settle cancelled err = %v", err)
524		}
525	
526		// 已预留请求的取消仍退回全部预留。
527		reserved := approvalApply()
528		reserved.RequestID = "r2"
529		reserved.EstimatedFee = 8
530		if _, err := w.Apply(reserved); err != nil {
531			t.Fatal(err)
532		}
533		if _, err := w.Cancel("u1", "r2"); err != nil {
534			t.Fatal(err)
535		}
536		bal, _ = w.Balance("payer")
537		if bal != (Balances{Available: 100, Reserved: 0}) {
538			t.Fatalf("balance after reserved cancel = %+v, want {100 0}", bal)
539		}
540	}
